{"file_path":"/app/merge_users.py","content":"#!/usr/bin/env python3
"""
Merge user data from three sources (A > B > C priority).

Sources:
  /data/source_a/users.json   - primary (highest priority)
  /data/source_b/users.csv     - secondary
  /data/source_c/users.parquet - tertiary

Outputs:
  /app/merged_users.parquet - one row per unique user
  /app/conflicts.json       - conflict report
"""

import json
from collections import defaultdict

import pandas as pd

SOURCE_PRIORITY = {"source_a": 0, "source_b": 1, "source_c": 2}

# Unified output fields (status is optional - only source_a provides it)
OUTPUT_FIELDS = ["name", "email", "created_date", "status"]
# Fields that can originate from more than one source and thus be in conflict.
CONFLICT_FIELDS = ["name", "email", "created_date"]


def normalize_records(records, mapping):
    """Rename source-specific fields to the unified schema."""
    normalized = []
    for rec in records:
        row = {}
        for unified, source_keys in mapping.items():
            for key in source_keys:
                if key in rec and rec[key] is not None:
                    row[unified] = rec[key]
                    break
        normalized.append(row)
    return normalized


def normalize_date(value):
    """Coerce a date-like value to a YYYY-MM-DD string."""
    if value is None:
        return None
    return pd.to_datetime(value).strftime("%Y-%m-%d")


# ---------------------------------------------------------------------------
# 1. Read and parse all three data sources
# ---------------------------------------------------------------------------
with open("/data/source_a/users.json", "r", encoding="utf-8") as f:
    source_a_raw = json.load(f)

source_b_raw = pd.read_csv("/data/source_b/users.csv").to_dict("records")
source_c_raw = pd.read_parquet("/data/source_c/users.parquet").to_dict("records")

# Field name mappings per source
A_MAPPING = {
    "user_id": ["id"],
    "name": ["full_name"],
    "email": ["email"],
    "created_date": ["registration_date"],
    "status": ["status"],
}
B_MAPPING = {
    "user_id": ["user_id"],
    "name": ["name"],
    "email": ["email_address"],
    "created_date": ["created_at"],
}
C_MAPPING = {
    "user_id": ["userId"],
    "name": ["userName"],
    "email": ["email"],
    "created_date": ["joined"],
}

# ---------------------------------------------------------------------------
# 2. Parse + map fields to the unified schema
# ---------------------------------------------------------------------------
tagged_records = []
for source, raw, mapping in (
    ("source_a", source_a_raw, A_MAPPING),
    ("source_b", source_b_raw, B_MAPPING),
    ("source_c", source_c_raw, C_MAPPING),
):
    for rec in normalize_records(raw, mapping):
        if "created_date" in rec:
            rec["created_date"] = normalize_date(rec["created_date"])
        rec["source"] = source
        tagged_records.append(rec)

# ---------------------------------------------------------------------------
# 3. Group by user_id (the merge key)
# ---------------------------------------------------------------------------
by_user = defaultdict(list)
for rec in tagged_records:
    uid = int(rec["user_id"])
    by_user[uid].append(rec)


def highest_priority_value(recs, field):
    """Return the value for `field` from the highest priority source that has it."""
    for rec in sorted(recs, key=lambda r: SOURCE_PRIORITY[r["source"]]):
        val = rec.get(field)
        if val is not None:
            return val
    return None


# ---------------------------------------------------------------------------
# 4. Merge with priority resolution + collect conflicts
# ---------------------------------------------------------------------------
merged_rows = []
conflicts = []

for uid in sorted(by_user):
    recs = by_user[uid]

    # Merged row: pick the highest-priority value per field
    row = {"user_id": uid}
    for field in OUTPUT_FIELDS:
        value = highest_priority_value(recs, field)
        if value is not None:
            row[field] = value
    merged_rows.append(row)

    # Conflict detection: user present in multiple sources with differing values
    for field in CONFLICT_FIELDS:
        values = {}
        for rec in recs:
            val = rec.get(field)
            if val is not None:
                values[rec["source"]] = val

        distinct_values = {str(v) for v in values.values()}
        if len(values) > 1 and len(distinct_values) > 1:
            conflicts.append(
                {
                    "user_id": uid,
                    "field": field,
                    "values": {
                        src: values[src]
                        for src in ("source_a", "source_b", "source_c")
                        if src in values
                    },
                    "selected": highest_priority_value(recs, field),
                }
            )

# ---------------------------------------------------------------------------
# 5. Write merged dataset to Parquet (correct types / formats)
# ---------------------------------------------------------------------------
merged_df = pd.DataFrame(
    merged_rows, columns=["user_id", "name", "email", "created_date", "status"]
)
merged_df["user_id"] = merged_df["user_id"].astype("int64")
for col in ("name", "email", "created_date", "status"):
    merged_df[col] = merged_df[col].astype("string")

merged_df.to_parquet("/app/merged_users.parquet", index=False)

# ---------------------------------------------------------------------------
# 6. Write conflict report JSON
# ---------------------------------------------------------------------------
report = {
    "total_conflicts": len(conflicts),
    "conflicts": conflicts,
}
with open("/app/conflicts.json", "w", encoding="utf-8") as f:
    json.dump(report, f, indent=2)

print("Merged rows:", len(merged_df))
print("Conflicts:", len(conflicts))
"}
